def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    opp_bids = []
    pressure_bids = []
    desperate_count = 0
    rich_count = 0
    low_req_count = 0

    for agent_id, opp in alive:
        if opp.get('budget', 0) >= 250:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('water_requirement', WATER_REQ) < WATER_REQ:
            low_req_count += 1

        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            opp_bids.append((agent_id, bid))
            if prev.get('status') == 'won':
                pressure_bids.append(bid)
            else:
                pressure_bids.append(bid * 0.92)

    highest_prev = 0.0
    second_prev = 0.0
    bob_prev = None
    cindy_prev = None
    for agent_id, bid in opp_bids:
        if bid > highest_prev:
            second_prev = highest_prev
            highest_prev = bid
        elif bid > second_prev:
            second_prev = bid
        if agent_id == 'Bob':
            bob_prev = bid
        if agent_id == 'Cindy':
            cindy_prev = bid

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    capacity = supply / float(WATER_REQ)
    if capacity >= 2.0:
        market_tightness = 0.2
    elif capacity >= 1.5:
        market_tightness = 0.45
    elif capacity >= 1.15:
        market_tightness = 0.7
    else:
        market_tightness = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2
    if no_water_days >= 1:
        urgency += 0.35
    urgency = min(1.0, urgency)

    base = DAILY_SALARY * (0.22 + 0.38 * market_tightness + 0.28 * urgency + 0.12 * scarcity)

    if pressure_bids:
        avg_pressure = sum(pressure_bids) / float(len(pressure_bids))
    else:
        avg_pressure = DAILY_SALARY * 0.45

    target = max(base, avg_pressure * (0.72 + 0.22 * urgency))

    if cindy_prev is not None and cindy_prev >= 160 and urgency < 0.7 and capacity >= 1.5:
        target = min(target, DAILY_SALARY * 0.62)

    if bob_prev is not None:
        if bob_prev <= 140 and urgency >= 0.35 and capacity < 2.0:
            target = max(target, bob_prev + 2.0)
        elif bob_prev >= 125 and urgency < 0.35 and capacity >= 1.5:
            target = min(target, bob_prev - 8.0)

    if desperate_count >= 2:
        target += 8.0
    elif desperate_count == 1:
        target += 4.0

    if rich_count >= 2 and urgency < 0.5:
        target -= 5.0

    if low_req_count >= 1 and capacity < 1.5:
        target += 5.0

    if hp <= 2 or no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.78
        target = max(target, floor_bid)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 0.58)

    if day >= 8:
        target += 4.0 * urgency

    max_safe = budget
    if hp > 4 and no_water_days == 0:
        max_safe = min(max_safe, DAILY_SALARY * 1.15)
    else:
        max_safe = min(max_safe, DAILY_SALARY * 1.55)

    bid = max(0.0, min(target, max_safe))

    if budget < DAILY_SALARY * 0.5:
        bid = min(bid, budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Identify Cindy-like aggressor by max yesterday bid
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate urgency: if we've already missed water days or low hp, bid more aggressively
    urgency = 0
    if my_hp <= 2:
        urgency += 2
    elif my_hp <= 4:
        urgency += 1
    if my_no_water_days >= 2:
        urgency += 1

    # Supply pressure: lower supply means fewer allocations; bid slightly more
    # supply is between 15 and 25; map to [0,1]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_pressure = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_pressure = 0.5

    # Base bid target: conserve when healthy and no strong prior aggressor
    if urgency == 0 and highest_prev_bid < DAILY_SALARY * 0.7:
        target = DAILY_SALARY * (0.45 + 0.15 * supply_pressure)
    else:
        # If someone previously bid high (Cindy), overbid just enough to steal.
        # Use a small premium over the highest previous bid, but cap by urgency.
        premium = 5.0 + 10.0 * supply_pressure
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # High aggressor: respond with a near-daily-salary bid if we are at risk.
            target = highest_prev_bid + premium
            if urgency >= 2:
                target = max(target, DAILY_SALARY * 0.9)
            else:
                target = min(target, DAILY_SALARY * 0.75)
        else:
            # Moderate aggressor: bid around 60-75% salary depending on urgency
            target = DAILY_SALARY * (0.6 + 0.15 * supply_pressure + 0.1 * urgency)
            if highest_prev_bid > 0:
                target = max(target, min(highest_prev_bid + premium * 0.6, DAILY_SALARY * 0.8))

    # Ensure we don't bid more than budget; also avoid bidding above a plausible daily cap
    # (game likely uses budget and salary as constraints)
    cap = my_budget
    # If budget is tiny, bid whatever we can to avoid immediate death
    if my_budget <= DAILY_SALARY * 0.2:
        target = my_budget
    else:
        # Keep a safety margin so we can continue later days
        safety = 0.15 if my_hp >= 5 else 0.05
        cap = my_budget * (1.0 - safety)
        if cap < 0:
            cap = 0.0
        target = min(target, cap)

    # If we are very low hp, prefer spending to secure water.
    if my_hp <= 1:
        target = min(my_budget, max(target, DAILY_SALARY * 0.85))

    # Final clamp to non-negative
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        bid = DAILY_SALARY * 0.6
    else:
        avg_bid = sum(yesterday_bids) / len(yesterday_bids)
        max_prev = max(yesterday_bids)
        if my_status['hp'] < 4:
            bid = min(my_status['budget'], max_prev * 1.05)
        else:
            bid = min(my_status['budget'], max(DAILY_SALARY * 0.5, avg_bid * 0.95))

    if day_context['supply'] < WATER_REQ * 2:
        bid *= 1.2

    return float(min(my_status['budget'], max(0, bid)))
